import math

def solve_for_b(b):
    # The equation is a^2 - (2^(b+1) - 1)a + 2*3^b = 0

    C_b = (2**(b+1)) - 1
    D_b = 2 * (3**b)

    # Discriminant: Delta = C_b^2 - 4*D_b
    discriminant = C_b**2 - 4 * D_b

    solutions = []

    if discriminant < 0:
        return None, "No real solutions"

    # Check if discriminant is a perfect square
    sqrt_d = math.isqrt(discriminant)
    if sqrt_d * sqrt_d != discriminant:
        return None, "Discriminant is not a perfect square"

    # Solutions for a: a = (C_b +/- sqrt_d) / 2

    # Check first root
    numerator1 = C_b + sqrt_d
    if numerator1 % 2 == 0:
        a1 = numerator1 // 2
        if a1 > 0:
            solutions.append((a1, b))

    # Check second root
    numerator2 = C_b - sqrt_d
    if numerator2 % 2 == 0:
        a2 = numerator2 // 2
        if a2 > 0 and (a2, b) not in solutions: # Avoid double counting if a1=a2
            solutions.append((a2, b))

    return solutions, None

results = []
for b in range(1, 11):
    solutions, error = solve_for_b(b)

    if solutions:
        sum_ab = sum(a + b for a, b in solutions)
        results.append({
            'b': b,
            'solutions': solutions,
            'sum_ab': sum_ab
        })
    else:
        results.append({
            'b': b,
            'solutions': [],
            'error': error
        })

for res in results:
    if res['solutions']:
        print(f"b={res['b']}: Solutions found {res['solutions']}. Sum(a+b) = {res['sum_ab']}")
    else:
        print(f"b={res['b']}: No positive integer solutions. Reason: {res.get('error', 'N/A')}")
